<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class ForwardingAgentmodel extends CI_Model{    function fnGetInfo($VarData, $VarStatus, $VarId = '')    {        $this->db->select('*')->from(KN_MASTER_AGENTS);        if ($VarData <> '') {            $ArrWhere['agentname'] = trim($VarData);        }        // if ($VarStatus <> '') {        //     $this->db->where_in('status', array($VarStatus));        // } else {        //     $this->db->where_in('status', array(1, 2));        // }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        $ArrWhere['type'] = '1';        if (!empty($ArrWhere)) {            $this->db->where($ArrWhere);        }        return $this->db->get()->result_array();    }    function fnCheck($VarData = '', $VarId = '') {        $this->db->from(KN_MASTER_AGENTS);        //$ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['agentname'] = trim($VarData);        }        $ArrWhere['type'] = '1';        // echo $this->db->get_compiled_select();        // die;        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveInfo($ArrBuyer)    {        $VarCompanyId = $ArrBuyer['companyid'];        $VarId = $ArrBuyer['id'];        $ArrResult = [];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetInfo($ArrBuyer['agentname'], 1);            if (empty($ArrCheckExist)) {                unset($ArrBuyer['id']);                $this->db->insert(KN_MASTER_AGENTS, $ArrBuyer);                $VarInsId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarInsId;                $ArrResult['eid'] = urlencode(base64_encode($VarInsId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This forwarding agent already exists";            }        } else {            $ArrCheckExist = $this->fnCheck($ArrBuyer['agentname'], $VarId);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_AGENTS, $ArrBuyer, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data!';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This forwarding agent already exists";            }        }        return $ArrResult;    }    function fnCount($VarAgent='',$VarEmail_id='',$VarMobno='',$VarContactPerson='',$VarAgentCategory='',$VarBrand_id='',$VarStatus='', $VarAfilter = '')    {        $ArrWhere = array();        if ($VarAgent <> '') {            $ArrWhere[] = "b.agentname like '%" . $VarAgent . "%'";        }        if ($VarEmail_id <> '') {            $ArrWhere[] = "b.emailid like '%" . $VarEmail_id . "%'";        }        if ($VarMobno <> '') {            $ArrWhere[] = "b.mobile like '%" . $VarMobno . "%'";        }        if ($VarContactPerson <> '') {            $ArrWhere[] = "b.contactperson like '%" . $VarContactPerson . "%'";        }        if ($VarAgentCategory <> '') {            $ArrWhere[] = "b.agent_categoryid like '%" . $VarAgentCategory . "%'";        }        if ($VarBrand_id <> '') {            $ArrWhere[] = "b.brand_id like '%" . $VarBrand_id . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "b.status=" . $VarStatus;        } else {            $ArrWhere[] = "b.status in(1,2)";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "b.agentname LIKE '" . $VarAfilter . "%'";        }        $ArrWhere[] = "b.type = '1' ";        $VarWhere = '';        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        if (@$ArrWhere[0] <> '') {            $VarWhere = 'WHERE ' . implode(" and ", $ArrWhere) . " AND b.companyid = " . $ArrUserLoggedInfo['companyid'];        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_AGENTS . " AS b INNER JOIN " . KN_USERS . " AS u ON b.updatedby = u.id " . $VarWhere;        $ObjRows = $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($VarAgent='',$VarEmail_id='',$VarMobno='',$VarContactPerson='',$VarAgentCategory='',$VarBrand_id='',$VarStatus='',$VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '')    {        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('agentname', 'contactname', 'status', 'dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarAgent <> '') {            $ArrWhere[] = "b.agentname like '%" . $VarAgent . "%'";        }        if ($VarEmail_id <> '') {            $ArrWhere[] = "b.emailid like '%" . $VarEmail_id . "%'";        }        if ($VarMobno <> '') {            $ArrWhere[] = "b.mobile like '%" . $VarMobno . "%'";        }        if ($VarContactPerson <> '') {            $ArrWhere[] = "b.contactperson like '%" . $VarContactPerson . "%'";        }        if ($VarAgentCategory <> '') {            $ArrWhere[] = "b.agent_categoryid like '%" . $VarAgentCategory . "%'";        }        if ($VarBrand_id <> '') {            $ArrWhere[] = "b.brand_id like '%" . $VarBrand_id . "%'";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "b.agentname LIKE '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "b.status=" . $VarStatus;        } else {            $ArrWhere[] = "b.status in(1,2)";        }        $ArrWhere[] = "b.type = '1' ";        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = 'WHERE ' . implode(" and ", $ArrWhere) . " AND b.companyid = " . $ArrUserLoggedInfo['companyid'];        }        // removed this line . " limit " . $VarLimitInfo in below query        $VarSqlLab = "SELECT b.id,b.agentname,b.emailid,b.mobile,b.contactperson,b.agent_categoryid,b.brand_id,b.datecreated,b.dateupdated,b.status,contactname FROM " . KN_MASTER_AGENTS . " AS b INNER JOIN " . KN_USERS . " AS u ON b.updatedby = u.id " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }    // function fnChangeComStat($checkboxids, $optvalue)    // {    //     $Arrids = json_decode($checkboxids, true);    //     $this->db->where_in('id', $Arrids);    //     if ($this->db->update(KN_MASTER_AGENTS, array('status' => $optvalue))) {    //         return true;    //     }    //     return false;    // }}   